                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 100]}
                    />
                    <Tooltip formatter={(v: number) => fmtPct(v)} />
                    <Legend />
                    <Bar dataKey="West" stackId="a" fill="#0ea5e9" />
                    <Bar dataKey="South" stackId="a" fill="#f59e0b" />
                    <Bar dataKey="Northeast" stackId="a" fill="#8b5cf6" />
                    <Bar dataKey="Midwest" stackId="a" fill="#14b8a6" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          ) : (
            <ChartCard
              title="Top-1 region by product"
              subtitle="Which Census region owns the tip of each liability book"
            >
              <div className="h-[320px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={productTop1}
                    layout="vertical"
                    margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      domain={[0, 40]}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <YAxis
                      type="category"
                      dataKey="short"
                      width={72}
                      tick={{ fontSize: 12 }}
                    />
                    <Tooltip
                      formatter={(v: number, _n, item) => [
                        fmtPct(v),
                        `${item?.payload?.top1Region ?? ""} tip`,
                      ]}
                    />
                    <Bar dataKey="top1SharePct" radius={[0, 4, 4, 0]}>
                      {productTop1.map((p) => (
                        <Cell key={p.short} fill={p.fill} />
                      ))}
                    </Bar>
                    <Line
                      type="monotone"
                      dataKey="top1SharePct"
                      stroke="#0f172a"
                      strokeWidth={0}
                      dot={false}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
              <ul className="mt-3 grid gap-1 text-sm text-slate-600 sm:grid-cols-2">
                {productTop1.map((p) => (
                  <li key={p.product}>
                    <span className="font-semibold text-slate-800">
                      {p.short}:
                    </span>{" "}
                    {p.top1Region} {fmtPct(p.top1SharePct)}
                  </li>
                ))}
              </ul>
            </ChartCard>
          )}
        </div>
      )}

      {view === "risk" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Debt share ?? card stress"
            subtitle="Bubble size = regional debt stock ($T)"
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Debt share"
                    unit="%"
                    domain={[18, 32]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Debt share %",
                      position: "insideBottom",
                      offset: -4,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Card 90+"
                    unit="%"
                    domain={[5, 9.5]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Card 90+ %",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[120, 420]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    labelFormatter={(_, payload) =>
                      String(payload?.[0]?.payload?.region ?? "")
                    }
                    formatter={(v: number, name: string) =>
                      name.includes("share") || name === "Debt share"
                        ? fmtPct(v)
                        : name.includes("90") || name === "Card 90+"
                          ? fmtPct(v)
                          : fmtTn(v)
                    }
                  />
                  <Scatter data={riskScatter}>
                    {riskScatter.map((d) => (
                      <Cell key={d.region} fill={d.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Debt activity vs deposit capacity"
            subtitle="X = debt share; Y = FDIC deposit share; bubble = wealth proxy"
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    domain={[18, 32]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Debt share %",
                      position: "insideBottom",
                      offset: -4,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    domain={[12, 36]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Deposit share %",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[80, 360]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    labelFormatter={(_, payload) =>
                      String(payload?.[0]?.payload?.region ?? "")
                    }
                    formatter={(v: number) => fmtPct(v)}
                  />
                  <Scatter data={cashScatter}>
                    {cashScatter.map((d) => (
                      <Cell key={d.region} fill={d.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Meter compare ??? Top-1 shares"
            subtitle="Different ledgers, different geographic tips"
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={meters}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 40]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number, _n, item) => [
                      fmtPct(v),
                      item?.payload?.top1Label ?? "Top-1",
                    ]}
                  />
                  <Bar dataKey="top1SharePct" radius={[0, 4, 4, 0]}>
                    {meters.map((m) => (
                      <Cell key={m.id} fill={m.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Card 90+ by region"
            subtitle={`National theme anchor ~${fmtPct(HEADLINE.nationalCardDelinqPct)}`}
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={delinqMeters}
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="region" tick={{ fontSize: 12 }} />
                  <YAxis
                    domain={[0, 10]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v: number) => fmtPct(v)} />
                  <Bar dataKey="rate" radius={[4, 4, 0, 0]}>
                    {delinqMeters.map((d) => (
                      <Cell key={d.region} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <div className="lg:col-span-2">
            <ChartCard title="Cash parking mix" subtitle="Deposit $T vs debt share by region">
              <div className="h-[260px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={CASH_PARKING}
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="short" tick={{ fontSize: 12 }} />
                    <YAxis
                      yAxisId="left"
                      tickFormatter={(v) => `$${v}T`}
                    />
                    <YAxis
                      yAxisId="right"
                      orientation="right"
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 40]}
                    />
                    <Tooltip />
                    <Legend />
                    <Bar
                      yAxisId="left"
                      dataKey="depositTn"
                      name="Deposits $T"
                      radius={[4, 4, 0, 0]}
                    >
                      {CASH_PARKING.map((r) => (
                        <Cell key={r.id} fill={r.fill} />
                      ))}
                    </Bar>
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="debtSharePct"
                      name="Debt share %"
                      stroke="#0f172a"
                      strokeWidth={2}
                      dot={{ r: 4 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

